        var targetName = loungeSeat ? loungeSeat.waypoint : "water_cooler";
        var actions = [
            officeAction("STAND"),
            officeWalkAction(agent.homeFloor, agent.deskDoorWpName),
            officeWalkAction(agent.homeFloor, targetName),
